  const theme = window.V2Store.getState().theme;
  const effective = theme === 'system' ? matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light' : theme;
  const shouldAnimate = animate && document.documentElement.dataset.theme !== effective;
  const themeDocuments = [document,...Object.values(frames).map(frame => frame.contentDocument),recordsPage.contentDocument].filter(Boolean);
  if (shouldAnimate) {
    clearTimeout(themeTransitionTimer);
    themeDocuments.forEach(doc => doc.documentElement.classList.add('theme-transition'));
    themeDocuments.forEach(doc => { void getComputedStyle(doc.body).backgroundColor; });
  }
  document.documentElement.dataset.theme = effective;
  [...Object.values(frames),recordsPage].forEach(frame => { if (frame.contentDocument?.documentElement) frame.contentDocument.documentElement.dataset.theme = effective; });
  settingsPage.classList.toggle('is-dark',effective === 'dark');
  if (shouldAnimate) themeTransitionTimer = setTimeout(() => themeDocuments.forEach(doc => doc.documentElement.classList.remove('theme-transition')),reducedMotionQuery.matches ? 150 : 450);
  try { localStorage.setItem('ndx-invest-frontend-v2-theme',theme); } catch (_) {}
}

