function applyTheme(animate=false) {
  const theme=window.V2Store.getState().theme,effective=theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):theme;
  const mine=frames['我的'].contentDocument,row=[...(mine?.querySelectorAll('.setting-row')||[])].find(r=>r.querySelector('.row-title')?.textContent==='深色模式');
  if(row)row.querySelector('.row-end > span').textContent={system:'跟随系统',light:'浅色模式',dark:'深色模式'}[theme];
  const commit=()=>{
    [document,...Object.values(frames).map(f=>f.contentDocument),recordsPage.contentDocument].filter(Boolean).forEach(doc=>{doc.documentElement.classList.remove('theme-transition');if(doc.documentElement.dataset.theme!==effective)doc.documentElement.dataset.theme=effective;});
    settingsPage.classList.toggle('is-dark',effective==='dark');pendingTheme=null;
  };
  try{localStorage.setItem('ndx-invest-frontend-v2-theme',theme);}catch(_){}
  if(pendingTheme===effective)return;
  clearTimeout(themeTransitionTimer);pendingTheme=null;
  let shade=document.getElementById('themeFadeShade');
  if(animate&&document.documentElement.dataset.theme!==effective&&!reducedMotionQuery.matches){
    if(!shade){shade=document.createElement('div');shade.id='themeFadeShade';shade.setAttribute('aria-hidden','true');shade.style.cssText='position:fixed;inset:0;z-index:500;pointer-events:none;opacity:0;will-change:opacity';document.body.append(shade);}
    shade.getAnimations().forEach(a=>a.cancel());shade.style.background=effective==='dark'?'#11151a':'#f5f6f8';
    shade.animate([{opacity:0},{opacity:.18,offset:.4},{opacity:0}],{duration:240,easing:'ease-in-out'});
    pendingTheme=effective;themeTransitionTimer=setTimeout(commit,96);
  }else{shade?.getAnimations().forEach(a=>a.cancel());commit();}
}

